<?php
namespace App\Modules\Accompagnement\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Tenancy\Services\OfficineAccess as Access;
use App\Modules\Identity\Services\Outbox;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Str;
class SupportRequestController extends Controller {
 private function fields():array{return ['title'=>['nullable','string','max:180'],'description'=>['nullable','string','max:5000'],'contact'=>['nullable','string','max:180'],'theme'=>['nullable','string','max:120'],'availability'=>['nullable','string','max:250'],'urgency'=>['sometimes','in:normal,high,low']];}
 private function row(int $office,string $id):object{$row=DB::table('support_requests')->where('officine_id',$office)->where('id',$id)->lockForUpdate()->first();abort_unless($row,404);return $row;}
 private function event(Request $r,int $office,int $id,string $action,int $version):void{Access::audit($r,$office,'support.request.'.$action,['request_id'=>$id,'version'=>$version]);}
 private function visible(Request $r,int $office){return DB::table('support_requests')->where('officine_id',$office)->where(fn($q)=>$q->where('status','!=','draft')->orWhere('created_by',$r->user()->id));}
 public function index(Request $r){$office=Access::admin($r);$d=$r->validate(['status'=>['nullable','in:draft,submitted,withdrawn'],'search'=>['nullable','string','max:180'],'page'=>['sometimes','integer','min:1']]);$counts=['draft'=>0,'submitted'=>0,'withdrawn'=>0];foreach($this->visible($r,$office)->select('status')->selectRaw('COUNT(*) as total')->groupBy('status')->get() as $count)$counts[$count->status]=(int)$count->total;$q=$this->visible($r,$office);if(!empty($d['status']))$q->where('status',$d['status']);if(!empty($d['search']))$q->where(fn($q)=>$q->where('title','like','%'.$d['search'].'%')->orWhere('reference','like','%'.$d['search'].'%'));$p=$q->latest('id')->paginate(25);$missions=DB::table('support_missions')->whereIn('support_request_id',$p->pluck('id'))->get()->keyBy('support_request_id');$p->getCollection()->transform(function($row)use($missions){$row->mission=$missions->get($row->id);return $row;});return response()->json(array_merge($p->toArray(),['summary'=>$counts]))->header('Cache-Control','no-store');}
 public function create(Request $r){$office=Access::admin($r);$d=$r->validate($this->fields()+['request_key'=>['required','string','min:16','max:80','regex:/^[A-Za-z0-9-]+$/']]);return DB::transaction(function()use($r,$office,$d){Access::lockAdmin($r,$office);$existing=DB::table('support_requests')->where('officine_id',$office)->where('request_key',$d['request_key'])->first();if($existing){abort_unless($existing->created_by===$r->user()->id,409);foreach($d as $k=>$v)abort_unless($existing->$k===$v,409,'Clé déjà utilisée pour un contenu différent.');return response()->json(['id'=>$existing->id],200);}$id=DB::table('support_requests')->insertGetId($d+['officine_id'=>$office,'created_by'=>$r->user()->id,'reference'=>'ACC-'.strtoupper(Str::random(16)),'created_at'=>now(),'updated_at'=>now()]);$this->event($r,$office,$id,'draft_created',1);return response()->json(['id'=>$id],201);});}
 public function save(Request $r,string $id){$office=Access::admin($r);$d=$r->validate($this->fields()+['version'=>['required','integer','min:1']]);DB::transaction(function()use($r,$office,$id,$d){Access::lockAdmin($r,$office);$row=$this->row($office,$id);abort_unless($row->created_by===$r->user()->id,404);abort_unless($row->status==='draft'&&$row->version===(int)$d['version'],409,'Demande non modifiable ou version périmée.');DB::table('support_requests')->where('id',$id)->update(array_replace($d,['version'=>$row->version+1,'updated_at'=>now()]));$this->event($r,$office,(int)$id,'draft_saved',$row->version+1);});return response()->json(['message'=>'Brouillon enregistré.']);}
 public function submit(Request $r,string $id){$office=Access::admin($r);$d=$r->validate(['version'=>['required','integer','min:1']]);DB::transaction(function()use($r,$office,$id,$d){Access::lockAdmin($r,$office);$row=$this->row($office,$id);abort_unless($row->created_by===$r->user()->id,404);if($row->status==='submitted'&&$row->version===(int)$d['version']+1)return;abort_unless($row->status==='draft'&&$row->version===(int)$d['version'],409);validator((array)$row,['title'=>['required','string','regex:/\S/u'],'description'=>['required','string','regex:/\S/u'],'contact'=>['required','string','regex:/\S/u']])->validate();DB::table('support_requests')->where('id',$id)->update(['status'=>'submitted','version'=>$row->version+1,'submitted_at'=>now(),'updated_at'=>now()]);$this->event($r,$office,(int)$id,'submitted',$row->version+1);Outbox::office($office,'service-request:'.$id.':submitted','Demande d’accompagnement soumise','Votre demande a été enregistrée. L’urgence déclarée ne garantit pas de délai de réponse.');});return response()->json(['message'=>'Demande soumise.']);}
 public function withdraw(Request $r,string $id){$office=Access::admin($r);$d=$r->validate(['version'=>['required','integer','min:1'],'reason'=>['required','string','max:2000','regex:/\S/u']]);DB::transaction(function()use($r,$office,$id,$d){Access::lockAdmin($r,$office);$row=$this->row($office,$id);abort_unless($row->status!=='draft'||$row->created_by===$r->user()->id,404);abort_unless(in_array($row->status,['draft','submitted'],true)&&$row->version===(int)$d['version'],409);$mission=DB::table('support_missions')->where('support_request_id',$id)->lockForUpdate()->first();abort_if($mission&&$mission->status==='accepted',409,'Une mission acceptée nécessite un parcours de clôture distinct.');if($mission&&$mission->status==='proposed')DB::table('support_missions')->where('id',$mission->id)->update(['status'=>'cancelled','version'=>$mission->version+1,'updated_at'=>now()]);DB::table('support_requests')->where('id',$id)->update(['status'=>'withdrawn','withdrawal_reason'=>trim($d['reason']),'version'=>$row->version+1,'updated_at'=>now()]);$this->event($r,$office,(int)$id,'withdrawn',$row->version+1);Outbox::office($office,'service-request:'.$id.':withdrawn','Demande d’accompagnement retirée','Une demande a été retirée ; son historique est conservé.');});return response()->json(['message'=>'Demande retirée sans suppression.']);}
}
